import { DEMO_TRACKS } from "./demoCatalog.js";
import type { MusicProvider, PlaybackAvailability, PlaybackSource, ProviderTrack } from "./types.js";

const toTrack = (t: (typeof DEMO_TRACKS)[number]): ProviderTrack => ({
  providerId: "demo",
  providerTrackId: t.id,
  title: t.title,
  artist: t.artist,
  album: t.album,
  durationMs: t.durationMs,
  genre: t.genre,
  artworkUrl: `/art/${t.id}.png`,
  audioPath: `/audio/${t.id}.mp3`,
  isKaraoke: t.album === "Sing Along",
});

/** VibeRoom's own catalog: original synthesized tracks generated by scripts/generate-demo-audio.ts. */
export class DemoProvider implements MusicProvider {
  readonly id = "demo";
  readonly name = "VibeRoom Demo Catalog";
  readonly capabilities = { canStreamDirectly: true, supportsSearch: true, requiresUserAuth: false };

  /** Test hook: simulate an outage. */
  failing = false;

  isConfigured() { return true; }

  async searchTracks(query: string): Promise<ProviderTrack[]> {
    if (this.failing) throw new Error("demo provider unavailable");
    const q = query.trim().toLowerCase();
    return DEMO_TRACKS.filter((t) => !q || [t.title, t.artist, t.album, t.genre].some((f) => f.toLowerCase().includes(q))).map(toTrack);
  }

  async getTrack(id: string) {
    if (this.failing) throw new Error("demo provider unavailable");
    const t = DEMO_TRACKS.find((x) => x.id === id);
    return t ? toTrack(t) : null;
  }

  async getPlaybackAvailability(id: string): Promise<PlaybackAvailability> {
    if (this.failing) return { status: "unavailable", reason: "Provider is temporarily unavailable" };
    return DEMO_TRACKS.some((x) => x.id === id)
      ? { status: "playable", via: "direct-audio" }
      : { status: "unavailable", reason: "Track is not in the demo catalog" };
  }

  async getPlaybackSource(id: string): Promise<PlaybackSource | null> {
    if (this.failing || !DEMO_TRACKS.some((x) => x.id === id)) return null;
    return { kind: "direct-audio", url: `/audio/${id}.mp3`, mimeType: "audio/mpeg" };
  }
}
